from datetime import datetime, timedelta
from typing import Dict, List, Optional


class Appointment:
    def __init__(
        self,
        id_: int,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        note: str = "",
    ) -> None:
        self.id = id_
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.note = note
        self.cancelled = False
        self.slot_blocked = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
        note: str = "",
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        # Check if the patient already has an upcoming appointment
        for appt in self._appointments.values():
            if not appt.cancelled and appt.patient == patient:
                # An appointment is considered upcoming if its end time (or start time) is in the future relative to now.
                # Commonly, an appointment that hasn't completed yet (end > now) is upcoming.
                # To be conservative and strictly follow "starts before now raises", upcoming means start >= now.
                if appt.start >= now:
                    raise ValueError(
                        f"Patient '{patient}' already has an upcoming appointment."
                    )

        # Check if doctor is free during the requested window
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available between {start} and {end}."
            )

        appt_id = self._next_id
        self._next_id += 1

        new_appt = Appointment(appt_id, patient, doctor, start, end, note=note)
        self._appointments[appt_id] = new_appt
        return appt_id

    def note(self, appointment_id: int) -> str:
        """Returns the note associated with the appointment."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")
        return self._appointments[appointment_id].note

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an existing appointment."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.cancelled:
            return

        appt.cancelled = True

        # Cancelling less than 24 hours before start retains the block on the time slot
        if appt.start - now >= timedelta(hours=24):
            appt.slot_blocked = False
        else:
            appt.slot_blocked = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            return False

        for appt in self._appointments.values():
            if appt.doctor == doctor and appt.slot_blocked:
                # Two intervals [start, end) and [appt.start, appt.end) overlap if:
                # max(start, appt.start) < min(end, appt.end)
                if max(start, appt.start) < min(end, appt.end):
                    return False

        return True

    def appointments_of(self, doctor: str) -> list[dict]:
        """Returns the doctor's appointments sorted by start time, each with keys id, patient, start, and end."""
        doctor_appts = [
            appt
            for appt in self._appointments.values()
            if appt.doctor == doctor and not appt.cancelled
        ]
        doctor_appts.sort(key=lambda appt: appt.start)
        return [
            {
                "id": appt.id,
                "patient": appt.patient,
                "start": appt.start,
                "end": appt.end,
            }
            for appt in doctor_appts
        ]
